REM ps-runner.bat
REM Launches a PowerShell script and logs all output to C:\Logs\
REM
REM Usage: Just double-click, or run from Command Prompt.
REM        Edit PS_SCRIPT and LOG_DIR below to match your setup.

set PS_SCRIPT=myscript.ps1
set LOG_DIR=C:\Logs

REM Create log directory if it doesn't exist
if not exist "%LOG_DIR%" mkdir "%LOG_DIR%"

REM Build a timestamped log filename
for /f "tokens=1-3 delims=/ " %%a in ('date /t') do set DATE_PART=%%c%%b%%a
for /f "tokens=1-2 delims=: " %%a in ('time /t') do set TIME_PART=%%a%%b
set LOGFILE=%LOG_DIR%\%PS_SCRIPT%-%DATE_PART%-%TIME_PART%.log

echo === PowerShell Script Runner ===
echo Script  : %PS_SCRIPT%
echo Log file: %LOGFILE%
echo.

REM Run the PowerShell script with execution policy bypass
REM Output goes to both the console window and the log file
powershell.exe -NoProfile -ExecutionPolicy Bypass -File "%~dp0%PS_SCRIPT%" 2&gt;&amp;1 | tee "%LOGFILE%"

if %errorlevel% equ 0 (
    echo.
    echo Script completed successfully.
    echo Log saved to: %LOGFILE%
) else (
    echo.
    echo Script FAILED with exit code %errorlevel%.
    echo Review the log at: %LOGFILE%
)

pause
</code></pre>  ### How to run this script — step by step  **Before you start — what you need** - Windows PowerShell (already on Windows 10/11) - The PowerShell script you want to run saved in the same folder as this batch file - The `C:\Logs\` folder (the batch file creates it automatically if it doesn't exist)  **Step 1 — Save the file**  1. Open **Notepad** (Windows key → search for Notepad) 2. Copy the entire code block above 3. Click **File → Save As** 4. Set "Save as type" to **All Files** (important — prevents Notepad adding .txt) 5. Name it `ps-runner.bat` and save to your Desktop  **Step 2 — Fill in your details**  Open the saved file and update these values near the top:  | Variable | What to enter | Where to find it | |---|---|---| | `PS_SCRIPT` | Filename of the PowerShell script to run, e.g. `windows-health-check.ps1` | The `.ps1` file you want to run (must be in the same folder as this batch file) | | `LOG_DIR` | Folder where log files are saved | Default: `C:\Logs` — will be created automatically |  **Step 3 — Open the right terminal**  - **For .bat / .cmd:** Open Command Prompt or just double-click the file  **Step 4 — Run it**  <pre><code>cd C:\Users\YourName\Desktop
ps-runner.bat
</code></pre>  Or just double-click the file from your Desktop.  **What you should see**  The PowerShell script runs and its output appears in the Command Prompt window in real time. At the same time, everything is saved to a timestamped log file in `C:\Logs\`. When it finishes, the window shows either "completed successfully" or "FAILED" and tells you where the log file is. The window stays open so you can read it.  ---  ## Windows: PowerShell Module Auto-Installer (PowerShell)  Automatically check and install the PowerShell modules most commonly needed for infrastructure work. Includes an example of using Posh-SSH for SSH connections from PowerShell.  <pre><code># Install-InfraModules.ps1
# Checks and installs required PowerShell modules for infrastructure work.
# Run as Administrator for system-wide install, or without for current user only.

$RequiredModules = @(
    @{ Name = "VMware.PowerCLI";   MinVersion = "13.0.0" },
    @{ Name = "Az";                MinVersion = "10.0.0" },
    @{ Name = "AWS.Tools.Common";  MinVersion = "4.0.0"  },
    @{ Name = "Posh-SSH";          MinVersion = "3.0.0"  }
)

$InstallScope = if ($IsWindows -and ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]"Administrator")) {
    "AllUsers"
} else {
    "CurrentUser"
}

Write-Host "`n=== PowerShell Module Auto-Installer ===" -ForegroundColor Cyan
Write-Host "Install scope : $InstallScope"
Write-Host "Time          : $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')`n"

Write-Host ("{0,-30} {1,-15} {2,-15} {3}" -f "Module", "Required", "Installed", "Status")
Write-Host ("-" * 75)

$results = foreach ($mod in $RequiredModules) {
    $name       = $mod.Name
    $minVersion = $mod.MinVersion

    $installed = Get-Module -ListAvailable -Name $name |
                 Sort-Object Version -Descending |
                 Select-Object -First 1

    if ($installed) {
        if ([Version]$installed.Version -ge [Version]$minVersion) {
            $status = "OK"
            $color  = "Green"
        } else {
            $status = "Outdated — updating"
            $color  = "Yellow"
        }
    } else {
        $status = "Missing — installing"
        $color  = "Red"
    }

    Write-Host ("{0,-30} {1,-15} {2,-15} " -f $name, $minVersion, ($installed.Version ?? "Not installed")) -NoNewline
    Write-Host $status -ForegroundColor $color

    [PSCustomObject]@{
        Name      = $name
        Required  = $minVersion
        Installed = $installed.Version ?? "Not installed"
        Status    = $status
    }
}

Write-Host ""

# Install or update modules that need it
foreach ($r in $results) {
    if ($r.Status -ne "OK") {
        Write-Host "Installing $($r.Name)..." -ForegroundColor Yellow
        try {
            Install-Module -Name $r.Name -MinimumVersion $r.Required -Scope $InstallScope -Force -AllowClobber
            Write-Host "  $($r.Name) installed successfully." -ForegroundColor Green
        } catch {
            Write-Host "  ERROR installing $($r.Name): $_" -ForegroundColor Red
        }
    }
}

Write-Host "`nAll modules checked." -ForegroundColor Cyan

# --- Example: Using Posh-SSH for SSH from PowerShell ---
Write-Host "`n--- Posh-SSH Example (SSH from PowerShell) ---" -ForegroundColor White
Write-Host @"
# Posh-SSH lets you SSH into Linux/network devices from PowerShell.
# No need for PuTTY or plink.

# Connect to a server (prompts for username/password):
`$cred    = Get-Credential
`$session = New-SSHSession -ComputerName "192.168.1.100" -Credential `$cred

# Run a command:
`$result = Invoke-SSHCommand -SessionId `$session.SessionId -Command "df -h"
`$result.Output

# Disconnect when done:
Remove-SSHSession -SessionId `$session.SessionId
"@
</code></pre>  ### How to run this script — step by step  **Before you start — what you need** - Windows PowerShell 5.1 or PowerShell 7 - Internet access so PowerShell can download modules from the PowerShell Gallery - Running as Administrator gives system-wide install; without it installs for your user only  **Step 1 — Save the file**  1. Open **Notepad** (Windows key → search for Notepad) 2. Copy the entire code block above 3. Click **File → Save As** 4. Set "Save as type" to **All Files** (important — prevents Notepad adding .txt) 5. Name it `Install-InfraModules.ps1` and save to your Desktop  **Step 2 — Fill in your details**  The `$RequiredModules` list near the top can be edited to add or remove modules:  | Field | What to enter | Example | |---|---|---| | `Name` | PowerShell module name from the Gallery | `"Az"` | | `MinVersion` | Minimum version you need | `"10.0.0"` |  **Step 3 — Open the right terminal**  - **For .ps1 (PowerShell):** Windows key → `PowerShell` → right-click → **Run as Administrator**  **Step 4 — Allow scripts to run (one-time per session)**  <pre><code>Set-ExecutionPolicy -Scope Process -ExecutionPolicy Bypass
</code></pre>  **Step 5 — Run it**  <pre><code>cd C:\Users\YourName\Desktop
.\Install-InfraModules.ps1
</code></pre>  **What you should see**  A table showing each module with its required version, currently installed version, and status (OK, Outdated, or Missing). Any missing or outdated modules are automatically downloaded and installed. At the end, an example snippet shows how to use Posh-SSH to connect to a Linux server directly from PowerShell.  ---  ---  ## Verify  - Confirm the operation completed without errors in the log or management UI - Verify the expected state change is visible (service running, object created, config applied) - Document the outcome in the change record  ---  ## See also  - [Windows Server — Procedures](../procedures/) - [Windows Server — CLI Reference](../cli-reference/) - [Windows Server — Health Checks](../health-checks/)

